function [u] = kpi_metric_unit(kind, unit_min)
%KPI_METRIC_UNIT  The unit a kind's value is stated in (a time to a threshold in minutes when unit_min).
%   kind: MetricKind (passed a choice, as its option's number)
%   unit_min: bool (passed true or false)
%   returns u: MetricUnit (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    u = 0;
    u = 0;
    if ((kind == 0) || (kind == 8))
        u = 1;
    elseif ((kind == 5) || (kind == 10))
        u = 3;
    elseif (kind == 6)
        u = 2;
        if unit_min
            u = 1;
        end
    elseif (kind == 7)
        u = 4;
    elseif (((kind == 11) || (kind == 29)) || (kind == 30))
        u = 5;
    elseif (kind == 12)
        u = 6;
    elseif (kind == 15)
        u = 8;
    elseif (((kind == 28) || (kind == 13)) || (kind == 14))
        u = 7;
    end
end
